  /** \u8868\u683C\u9879\u52A8\u4F5C column \u7684\u914D\u7F6E */
  columnActionsConfig?: ProTableColumnType<R>

  /** \u8868\u683C\u6570\u636E\u4E3A\u7A7A\u65F6\u9690\u85CF\u6240\u6709\u7684\u5217\uFF0C\u7528\u5728 columns \u9879\u8F83\u591A\u4F46\u6570\u636E\u4E3A\u7A7A\u65F6\uFF0C\u4F18\u5316\u5448\u73B0\u6548\u679C */
