  /** \u589E */
  onAdd?: <T = any>(params: any) => Promise<ProTableResponse<any> | void> | void

  /** \u6539 */
  onEdit?: <T = any>(params: any, item: R) => Promise<ProTableResponse<any> | void> | void

  /** \u7F16\u8F91\u6210\u529F\u540E\u5237\u65B0\u8868\u683C */
