import { ProTable } from '@fexd/pro-components'
import { Random } from 'mockjs'
import { message } from 'antd'
import { delay, sample, run, random } from '@fexd/tools'

const mockOptions = [
  { label: '\u9009\u98791', value: 1 },
  { label: '\u9009\u98792', value: 2 },
  { label: '\u9009\u98793', value: 3 },
  { label: '\u9009\u98794', value: 4 },
  { label: '\u9009\u98795', value: 5 },
]

export default () => (
  <ProTable
    actions={['add']}
    columns={[
      {
        title: '\u6587\u672C',
        dataIndex: 'text',
        width: '50%',
        addField: true,
      },
      {
        title: '\u5355\u9009\u6846',
        dataIndex: 'select',
        width: '50%',
        valueType: 'select',
        valueEnum: mockOptions,
        addField: true,
      },
    ]}
    renderModalAddFields={({ renderField, renderFields }) => {
      const [count, setCount] = useState(0)

      return (
        <>
          <div>count: {count}</div>
          {renderField('select')}
          {renderFields([
            ['text', <button onClick={() => setCount(count + 1)}>+</button>, 'select'],
            ['text'],
            ['text', 'select', 'text'],
            [
              { name: 'select', colSpan: 16 },
              { name: 'text', colSpan: 8 },
            ],
            [
              { colSpan: 16, content: <div>\u81EA\u5B9A\u4E49\u8282\u70B91</div> },
              { colSpan: 8, content: <div>\u81EA\u5B9A\u4E49\u8282\u70B92</div> },
            ],
          ])}
        </>
      )
    }}
  />
)`},react:{type:"NPM",value:"16.14.0"},"@fexd/pro-components":{type:"NPM",value:"0.2.99"}}}}},xr={title:"\u65B0\u589E",toc:"menu",filename:"documents/table/add.md",order:5,description:"\u8BE5\u529F\u80FD\u7531 editField \u63D2\u4EF6\u7BA1\u7406\uFF0C\u53EF\u53C2\u8003\u8BBF\u95EE\u5185\u90E8\u63D2\u4EF6\u53D6\u5F97\u63D2\u4EF6\u5B9E\u4F8B"},Dr=[{id:"\u5185\u7F6E\u65B0\u589E",depth:1,title:"\u5185\u7F6E\u65B0\u589E"},{id:"\u57FA\u7840\u7528\u6CD5",depth:2,title:"\u57FA\u7840\u7528\u6CD5"},{id:"\u4ECE-columns-\u7EE7\u627F",depth:2,title:"\u4ECE columns \u7EE7\u627F"},{id:"\u8868\u5355\u6821\u9A8C",depth:2,title:"\u8868\u5355\u6821\u9A8C"},{id:"\u8868\u5355\u5173\u8054",depth:2,title:"\u8868\u5355\u5173\u8054"},{id:"\u81EA\u5B9A\u4E49\u5E03\u5C40",depth:2,title:"\u81EA\u5B9A\u4E49\u5E03\u5C40"},{id:"\u5185\u8054-label",depth:3,title:"\u5185\u8054 label"},{id:"\u5B8C\u5168\u81EA\u5B9A\u4E49",depth:3,title:"\u5B8C\u5168\u81EA\u5B9A\u4E49"},{id:"\u5185\u7F6E\u7684\u8868\u5355\u7C7B\u578B",depth:2,title:"\u5185\u7F6E\u7684\u8868\u5355\u7C7B\u578B"},{id:"\u81EA\u5B9A\u4E49\u8868\u5355\u7C7B\u578B",depth:2,title:"\u81EA\u5B9A\u4E49\u8868\u5355\u7C7B\u578B"}],Kr=[{value:"\u8BE5\u529F\u80FD\u7531 ",paraId:0,tocIndex:0},{value:"editField",paraId:0,tocIndex:0},{value:" \u63D2\u4EF6\u7BA1\u7406\uFF0C\u53EF\u53C2\u8003",paraId:0,tocIndex:0},{value:"\u8BBF\u95EE\u5185\u90E8\u63D2\u4EF6",paraId:1,tocIndex:0},{value:"\u53D6\u5F97\u63D2\u4EF6\u5B9E\u4F8B",paraId:0,tocIndex:0},{value:"\u4EE5\u53CA\u53EF\u53C2\u8003 editField \u63D2\u4EF6",paraId:2,tocIndex:0},{value:"\u63D0\u4F9B\u7684\u529F\u80FD",paraId:3,tocIndex:0},{value:`// \u7F16\u8F91\u3001\u65B0\u589E\u3001\u8BE6\u60C5\u5F39\u7A97\u7684 modal \u63A7\u5236\u5668\uFF0C\u6709 { close, promise, update } \u51E0\u4E2A\u65B9\u6CD5
